package com.example.woundmanagement.ui.strings

import androidx.compose.runtime.Composable

/**
 * Helper inline per stringhe UI in 4 lingue (IT/EN/FR/ES) usabile fuori da `object S`,
 * direttamente al call site, con la stessa logica di lingua di `S.loc`.
 * Per le lingue diverse dall'italiano il valore è esplicito.
 * NON usare per i contenuti clinici validati delle scale (restano IT/EN d'origine).
 */
@Composable
fun loc4(it: String, en: String, fr: String, es: String): String =
    when (LocalLanguage.current) {
        AppLanguage.IT -> it
        AppLanguage.EN -> en
        AppLanguage.FR -> fr
        AppLanguage.ES -> es
    }

/** Variante non-composable, per contesti senza Composable (es. generazione PDF). */
fun loc4(lang: AppLanguage, it: String, en: String, fr: String, es: String): String =
    when (lang) {
        AppLanguage.IT -> it
        AppLanguage.EN -> en
        AppLanguage.FR -> fr
        AppLanguage.ES -> es
    }

